const date=s=>new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const STORE='richmount-classroom-v1';
let client=null,options={},teacher={loggedIn:false,loading:false,view:'inbox',students:[],archived:[],submissions:[],summary:{},total:0,offset:0,filters:{student:'',kind:'',reviewed:'',context:'',week:''},detail:null,error:'',reviewDrafts:{},bulkDraft:'',materials:null,materialsLoading:false,materialsError:''};
