let studentMaterials=null,studentMaterialsOwner='',studentMaterialsFlight=null,studentMaterialsGeneration=0,studentMaterialsError='',studentMaterialsUpdated=0;
const action=(label,name,extra='',style='')=>`<button class="button ${style}" data-cloud-action="${name}" ${extra}>${label}</button>`;

// Outbox entries carry a student ID, so work awaiting a retry cannot be sent as
// a different student after someone switches class codes on a shared device.
export function createStudentSync({storage,fetcher,apiBase,onChange=()=>{},onJoined=()=>{}}){
  let data={student:null,code:'',outbox:[],sent:{},records:[],courseResults:{}};try{data={...data,...JSON.parse(storage.getItem(STORE)||'{}')};}catch{}
  let sending=false,error='',flight=null,joinGeneration=0;
  if(data.code&&!data.code.startsWith('RMS.')){data.student=null;data.code='';data.records=[];persist();}
  function changed(){onChange();}
  function persist(){try{storage.setItem(STORE,JSON.stringify(data));return true;}catch{error='Your device could not save the sending queue. Keep this tab open and download a report as a backup.';return false;}}
  async function request(path,init={},code=data.code){
    if(!apiBase)throw new Error('Your teacher is finishing the classroom connection. You can continue practising here.');
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),init.audio?70000:init.ai?60000:20000);
    try{const response=await fetcher(apiBase+path,{...init,credentials:'omit',headers:{'Content-Type':'application/json','Authorization':'Bearer '+code,...init.headers},signal:controller.signal});if(response.ok&&init.binary)return response.blob();let value;try{value=await response.json();}catch{throw new Error('The classroom could not be reached. Your work remains saved on this device.');}if(!response.ok){if(response.status===401&&data.student&&data.code===code){leave();}throw new Error(value.error||'Please try again.');}return value;}
    finally{clearTimeout(timer);}
  }
  const status=id=>!data.student?'':data.sent[data.student.id+':'+id]?'sent':data.outbox.some(x=>x.studentId===data.student.id&&x.entry.id===id)?'pending':'';
  function flush(){
    if(flight)return flight;
    if(!data.student||!data.code||data.student.passwordChangeRequired)return Promise.resolve();
    const owner=data.student.id,code=data.code;sending=true;error='';
    flight=Promise.resolve().then(async()=>{
      try{while(data.student?.id===owner&&data.code===code){
        const item=data.outbox.find(x=>x.studentId===owner);if(!item)break;
        const course=item.entry.coursePacket,book=item.entry.bookPacket;
        const result=await request(book?'/api/student/books/'+encodeURIComponent(item.entry.bookId)+'/activities/'+encodeURIComponent(item.entry.bookActivityId)+'/submissions':course?'/api/student/course/'+encodeURIComponent(item.entry.activityId)+'/submissions':'/api/student/submissions',{method:'POST',body:JSON.stringify(course||book?{packet:item.entry.packet}:{entry:item.entry})},code);
        data.sent[owner+':'+item.entry.id]=result.submission.id;
        if(course||book){data.courseResults[owner+':'+item.entry.id]={submissions:result.submissions,review:result.review};const keys=Object.keys(data.courseResults);while(keys.length>80)delete data.courseResults[keys.shift()];}
        data.outbox=data.outbox.filter(x=>x!==item);const records=result.submissions||[result.submission];if(data.student?.id===owner)data.records=[...records,...data.records.filter(r=>!records.some(n=>n.id===r.id))].slice(0,100);persist();changed();
      }}catch(e){error=e.name==='AbortError'?'The classroom took too long to respond. Your work is waiting safely; choose Send pending work to retry.':e.message;}
    }).finally(()=>{sending=false;flight=null;changed();if(!error&&data.student?.id!==owner&&data.outbox.some(x=>x.studentId===data.student?.id))void flush();});
    changed();return flight;
  }

  function queue(entry){
    if(!data.student||data.student.passwordChangeRequired)return false;const current=status(entry.id);if(current)return true;
    if(data.outbox.length>=100){error='The sending queue is full. Send pending work before adding another report.';changed();return false;}
    data.outbox.push({studentId:data.student.id,entry:JSON.parse(JSON.stringify(entry))});persist();changed();void flush();return true;
  }
  async function join(code,password){
    const generation=++joinGeneration,joinCode=String(code).trim().toUpperCase();error='';
    try{const result=await request('/api/student/login',{method:'POST',body:JSON.stringify({studentCode:joinCode,password})},'');if(generation!==joinGeneration)return;data.code=result.token;data.student=result.student;data.records=[];persist();onJoined(result.student.name);changed();if(!data.student.passwordChangeRequired){await refresh();void flush();}}
    catch(e){if(generation===joinGeneration){error=e.message;changed();}throw e;}
  }
  async function changePassword(currentPassword,newPassword,confirmPassword){
    const owner=data.student?.id,token=data.code,result=await request('/api/student/password',{method:'POST',body:JSON.stringify({currentPassword,newPassword,confirmPassword})},token);
    if(data.student?.id!==owner||data.code!==token)throw new Error('Your account changed. Sign in again.');
    data.code=result.token;data.student=result.student;persist();changed();await refresh();void flush();return true;
  }
  async function refresh(){if(!data.student)return;const owner=data.student.id,code=data.code;try{const result=await request('/api/student/submissions',{},code);if(data.student?.id!==owner||data.code!==code)return;data.records=result.submissions;persist();error='';changed();}catch(e){if(data.student?.id===owner&&data.code===code){error=e.message;changed();}}}
  function leave(){joinGeneration++;data.student=null;data.code='';data.records=[];error='';persist();changed();}
  return {join,changePassword,leave,queue,flush,refresh,status,request,courseResult:id=>data.courseResults[data.student?.id+':'+id],submissionId:id=>data.sent[data.student?.id+':'+id],fileAccess:id=>request('/api/student/materials/'+encodeURIComponent(id)+'/access'),info:()=>({student:data.student,records:data.records,error,sending,pending:data.student?data.outbox.filter(x=>x.studentId===data.student.id).length:0,apiBase}),verify:async()=>{if(!data.code)return;const token=data.code,owner=data.student?.id;try{const result=await request('/api/student/me',{},token);if(data.code!==token||data.student?.id!==owner)return;data.student=result.student;persist();changed();if(!data.student.passwordChangeRequired){await refresh();void flush();}}catch(e){if(data.code===token){error=e.message;changed();}throw e;}}};
}
function notice(){const d=client?.info();return d?.error?`<div class="notice warm" role="alert">${esc(d.error)}</div>`:'';}
export function cloudHistoryLabel(id){
  const status=client?.status(id);return status==='sent'?'<span class="pill cloud-sent">✓ Sent to teacher</span>':status==='pending'?'<span class="pill">Waiting to send</span>':client?.info().student?action('Send to teacher','send-entry',`data-entry="${esc(id)}"`,'soft'):'';
}
export function refreshWritingProgress(){return client?.refresh();}
export function queueSubmission(entry){if(!isTeacherSite())client?.queue(entry);}
export function isClassConnected(){const student=client?.info().student;return !isTeacherSite()&&!!student&&!student.passwordChangeRequired;}
export function classroomOrigin(){return apiBase();}
export async function studentMaterialAccess(id){if(!isClassConnected())throw new Error('Join your class to open lesson materials.');return client.fileAccess(id);}
export async function teacherMaterialAccess(id){try{return await teacherRequest('/api/teacher/materials/'+encodeURIComponent(id)+'/access');}catch(error){if(!teacher.loggedIn)options.onChange?.();throw error;}}
function clearStudentMaterials(){studentMaterialsGeneration++;studentMaterials=null;studentMaterialsFlight=null;studentMaterialsError='';studentMaterialsUpdated=0;}
function loadStudentMaterials(force=false){
  if(!isClassConnected())return Promise.resolve();
  if(studentMaterialsOwner!==studentId()){clearStudentMaterials();studentMaterialsOwner=studentId();}
  if(studentMaterialsFlight)return studentMaterialsFlight;
  if(studentMaterials&&!force&&Date.now()-studentMaterialsUpdated<30000)return Promise.resolve();
  const generation=studentMaterialsGeneration,owner=studentId();studentMaterialsError='';
  studentMaterialsFlight=Promise.resolve().then(()=>client.request('/api/student/materials')).then(catalog=>{
    if(generation===studentMaterialsGeneration&&owner===studentId()){studentMaterials=catalog;studentMaterialsUpdated=Date.now();}
  }).catch(error=>{if(generation===studentMaterialsGeneration)studentMaterialsError=error.message;}).finally(()=>{
    if(generation===studentMaterialsGeneration){studentMaterialsFlight=null;options.onChange?.();}
  });
  return studentMaterialsFlight;
}
export function studentMaterialsPage({listeningOnly=false}={}){
  if(!isClassConnected())return materialsPage({isConnected:false,listeningOnly});
  if(studentMaterialsOwner!==studentId()){clearStudentMaterials();studentMaterialsOwner=studentId();}
  if(!studentMaterialsError&&!studentMaterialsFlight)void loadStudentMaterials();
  const error=studentMaterialsError?`<div class="notice warm" role="alert">${esc(studentMaterialsError)}</div>`:'';
  return `<div class="button-row" style="margin-bottom:16px">${action(studentMaterialsFlight?'Refreshing materials…':'Refresh materials','student-materials-retry',studentMaterialsFlight?'disabled':'','secondary')}</div>`+error+(studentMaterials?materialsPage({catalog:studentMaterials,isConnected:true,listeningOnly}):studentMaterialsError?'':materialsPage({catalog:null,isConnected:true,listeningOnly}));
}
export function studentName(){return isTeacherSite()?'':client?.info().student?.name||'';}
export function studentId(){return isTeacherSite()?'':client?.info().student?.id||'';}
export function classroomSessionState(){return {teacher:isTeacherSite(),connected:isTeacherSite()?teacher.loggedIn:!!client?.info().student,busy:loggingOut};}
export async function logoutClassroom(){
 if(loggingOut||!classroomSessionState().connected)return false;
 loggingOut=true;
 try{
  await options.beforeLogout?.();options.onChange?.();
  if(isTeacherSite()){
   teacherSessionGeneration++;
   await teacherRequest('/api/teacher/logout',{method:'POST',body:'{}'});
   teacher.loggedIn=false;teacher.loading=false;teacher.detail=null;teacher.students=[];teacher.archived=[];teacher.submissions=[];teacher.summary={};teacher.total=0;teacher.offset=0;teacher.reviewDrafts={};teacher.aiReports={};teacher.aiBusy='';teacher.fileBusy=false;aiSettings=null;teacher.bulkDraft='';clearTeacherMaterials();resetTeacherCourse();resetGuidedLessons();resetBookGrades();teacher.error='';
   location.hash='teacher/overview';
  }else{client.leave();location.hash='class';}
  options.onLoggedOut?.();options.toast?.('You are logged out. Your saved work is kept.');return true;
 }catch(error){throw new Error('Log out could not be completed. Reconnect and try again.');}
 finally{loggingOut=false;options.onChange?.();}
}
