export function openCourseInbox(week,context,studentId='',weeklyKey=''){teacher.view='inbox';teacher.detail=null;teacher.filters={...teacher.filters,week:String(week),context,student:studentId,weekly:weeklyKey,kind:'',reviewed:''};teacher.offset=0;location.hash='teacher/inbox';void refreshTeacher();}
export async function ensureSpeakingSubmission(entry){
  if(!isClassConnected())throw new Error('Join your class before uploading speaking audio.');
  const owner=studentId();client.queue(entry);await client.flush();
  if(owner!==studentId())throw new Error('Your class code changed. Reopen your own speaking activity.');
  const id=client.submissionId(entry.id);if(!id)throw new Error('Your notes are waiting to send. Retry when the classroom is available.');return id;
}
export function speakingSubmissionId(id){return client?.submissionId(id)||'';}

export function progressCloudHTML(){
  const d=client?.info();return writingProgressHTML(d?.records||[])+`<section class="card class-progress"><div class="section-head"><h3>Work shared with Teacher Angelo</h3><a href="#class">Your class →</a></div>${notice()}${d?.student?`${d.pending?`<p>${d.pending} ${d.pending===1?'activity is':'activities are'} waiting to send.</p>${action('Send pending work','retry')}`:''}${feedbackCards(d.records)}`:`<p>Join your class to send completed work and receive your teacher’s feedback.</p><a class="button soft" href="#class">Join your class →</a>`}</section>`;
}
const feedbackAccept='.pdf,.docx,.txt,.png,.jpg,.jpeg,.webp';
function feedbackFileList(files,role){return files.length?`<ul class="feedback-files">${files.map(f=>`<li><strong>${esc(f.filename)}</strong> <small>${Math.ceil(f.size/1024)} KB${role==='teacher'?' · '+(f.published?'Published':'Private draft'):''}</small><div class="button-row">${action('Download','download-feedback-file',`data-id="${esc(f.id)}" data-filename="${esc(f.filename)}" data-role="${role}"`,'soft')}${role==='teacher'?action('Remove','remove-feedback-file',`data-id="${esc(f.id)}"`,'secondary'):''}</div></li>`).join('')}</ul>`:'<p class="small muted">No feedback files attached.</p>';}
function teacherFeedbackFilesHTML(row){return `<section class="class-audio-panel"><h4>Feedback files</h4><p class="small muted">PDF, Word (.docx), text and images · 10 MB per file · up to 10 files. New files stay private until you publish. Removing a file takes it out of the student view immediately.</p>${feedbackFileList(row.attachments||[],'teacher')}<label class="audio-file-label button soft">${teacher.fileBusy?'Uploading…':'Attach feedback files'}<input type="file" multiple accept="${feedbackAccept}" data-feedback-upload="${esc(row.id)}" ${teacher.fileBusy?'disabled':''}></label></section>`;}
function studentFeedbackFilesHTML(row){return row.reviewed&&row.feedback_file_count?`<section><h4>Files from your teacher</h4>${action('View feedback files · '+row.feedback_file_count,'view-feedback-files',`data-id="${esc(row.id)}"`,'soft')}<div data-feedback-files="${esc(row.id)}" aria-live="polite"></div></section>`:'';}
function saveFeedbackDownload(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function keepFeedbackEditor(){const form=document.querySelector('#reviewForm');if(form&&teacher.detail)teacher.reviewDrafts[teacher.detail.id]={feedback:form.querySelector('#teacherFeedback').value,teacherScore:form.querySelector('#teacherMark').value,reviewed:false};}
function feedbackCards(records){return records?.length?`<div class="cloud-records">${records.map(r=>`<article class="cloud-feedback"><div><span class="pill">${esc(r.kind)} · ${r.reviewed?'Reviewed':'Awaiting review'}</span><h4>${esc(r.title)}</h4><p class="small muted">${date(r.created_at)}${r.score!=null?' · '+r.score+'/'+r.total+' practice marks':''}</p></div>${r.reviewed?`<div class="teacher-comment"><strong>Teacher Angelo’s feedback${r.teacher_score?' · '+esc(r.teacher_score):''}</strong><p class="preserve-lines">${esc(r.feedback||'Reviewed by your teacher.')}</p></div>`:'<p class="small muted">Sent successfully. Your teacher will review this activity.</p>'}${automaticFeedbackCard(r)}${studentFeedbackFilesHTML(r)}${studentAudioHTML(r.id,r.kind)}</article>`).join('')}</div>`:'<p class="small muted">Complete an activity, then submit it to see your shared work here.</p>';}
function studentPasswordHTML(required){return `<section class="card class-join student-password" style="margin-top:20px"><h2>${required?'Choose your new password':'Change your password'}</h2><p>${required?'Type your student code as your current password, then choose a password of your own.':'Type your current password to choose a new one.'}</p>${studentPasswordError?`<p class="notice warm" role="alert">${esc(studentPasswordError)}</p>`:''}<form id="studentPasswordForm"><label for="studentCurrentPassword">${required?'Current password (your student code)':'Current password'}</label><input id="studentCurrentPassword" name="currentPassword" type="password" autocomplete="current-password" maxlength="200" required><label for="studentNewPassword">New password (12–200 characters)</label><input id="studentNewPassword" name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><label for="studentConfirmPassword">Confirm new password</label><input id="studentConfirmPassword" name="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><button class="button">Save new password</button></form><p class="small muted">Keep your student code for signing in. If you forget your password, ask Teacher Angelo to reset it. Your work stays saved.</p></section>`;}
export function classroomPage(){
  const d=client?.info()||{};
  const head=`<div class="page-head"><div class="eyebrow">LEARN TOGETHER. KEEP GROWING.</div><h1>Your Richmount class.</h1><p>Send completed work to Teacher Angelo and read his feedback here.</p></div>${notice()}`;
  if(d.student)return head+`<section class="card class-member"><span class="pill cloud-sent">✓ Signed in</span><h2>${esc(d.student.name)}</h2><p>${d.student.passwordChangeRequired?'Set your new password below to open your class resources.':'Newly completed activities are sent to your teacher. Drafts stay on this device. If your connection drops, completed work waits here until you send it again.'}</p>${d.student.passwordChangeRequired?'':`<div class="button-row">${action(d.sending?'Sending…':'Send pending work'+(d.pending?' · '+d.pending:''),'retry',d.sending?'disabled':'')}${action('Refresh teacher feedback','student-refresh','','secondary')}</div>`}</section>`+studentPasswordHTML(d.student.passwordChangeRequired)+(d.student.passwordChangeRequired?'':`<section class="card" style="margin-top:20px"><h3>Earlier work on this device</h3><p class="small muted">You can choose to send reports completed before joining. Send only your own work, especially on a shared computer.</p>${action('Choose saved activities','choose-saved','','soft')}</section><section class="card" style="margin-top:20px"><h3>Your teacher’s feedback</h3>${feedbackCards(d.records)}</section>${studentLibraryHTML()}`);
  return head+`<section class="card class-join"><div class="class-join-icon">↗</div><h2>Sign in to your learning space.</h2><p>Use the individual student code from Teacher Angelo.</p><form id="classJoinForm"><label for="classCode">Student code</label><input id="classCode" name="username" required autocomplete="username" spellcheck="false" maxlength="40" placeholder="RM-…"><label for="studentLoginPassword">Password</label><input id="studentLoginPassword" name="password" type="password" autocomplete="current-password" maxlength="200" required><p class="small muted">First sign-in or after a teacher reset: enter your student code as your password. You will then choose a new password.</p><p class="small muted">By signing in, you choose to share completed essays, answers, practice scores and speaking notes with your teacher.</p><button class="button" ${!d.apiBase?'disabled':''}>Sign in →</button>${!d.apiBase?'<p class="small muted">The classroom connection is being set up. Your practice activities are available now.</p>':''}</form><p class="small muted">Forgot your password? Ask Teacher Angelo to use Reset password in your student record.</p></section>`;
}
const apiBase=()=>client?.info().apiBase||'';
export function isTeacherSite(){const base=(apiBase()||CLASSROOM_API).replace(/\/$/,'');return !!base&&base===location.origin;}
function clearTeacherMaterials(){materialsGeneration++;materialsFlight=null;teacher.materials=null;teacher.materialsLoading=false;teacher.materialsError='';}
async function teacherRequest(path,init={}){if(loggingOut&&path!=='/api/teacher/logout')throw new Error('Logging out. Please wait.');const generation=teacherSessionGeneration,response=await fetch(apiBase()+path,{...init,signal:AbortSignal.timeout(init.audio?70000:init.ai?60000:20000),credentials:'include',headers:{'Content-Type':'application/json',...init.headers}});if(response.ok&&init.binary){if(generation!==teacherSessionGeneration)throw new Error('Your teacher session changed. Sign in again.');return response.blob();}let value;try{value=await response.json();}catch{throw new Error('The teacher dashboard could not be reached. Please try again.');}if(generation!==teacherSessionGeneration&&path!=='/api/teacher/logout')throw new Error('Your teacher session changed. Sign in again.');if(response.status===401){teacher.loggedIn=false;clearTeacherMaterials();resetTeacherCourse();resetGuidedLessons();options.onChange?.();}if(!response.ok)throw new Error(value.error||'Please try again.');return value;}
function loadTeacherMaterials(force=false){
  if(!teacher.loggedIn||!isTeacherSite())return Promise.resolve();
  if(materialsFlight)return materialsFlight;
  if(teacher.materials&&!force)return Promise.resolve();
  const generation=materialsGeneration;
  teacher.materialsLoading=true;teacher.materialsError='';
  materialsFlight=Promise.resolve().then(()=>teacherRequest('/api/teacher/materials')).then(catalog=>{
    if(generation===materialsGeneration&&teacher.loggedIn)teacher.materials=catalog;
  }).catch(error=>{
    if(generation===materialsGeneration)teacher.materialsError=error.message;
  }).finally(()=>{
    if(generation===materialsGeneration){teacher.materialsLoading=false;materialsFlight=null;}
    options.onChange?.();
  });
  return materialsFlight;
}
function teacherMaterialsHTML(listeningOnly=false,skill=''){
  if(!teacher.materials&&!teacher.materialsLoading&&!teacher.materialsError)void loadTeacherMaterials();
  const error=teacher.materialsError?`<section class="notice warm" role="alert"><strong>Your learning materials could not load.</strong><p>${esc(teacher.materialsError)}</p>${action('Try again','teacher-materials-retry','','secondary')}</section>`:'';
  const catalog=teacher.materials&&(listeningOnly||skill)?{...teacher.materials,lessons:teacher.materials.lessons.filter(lesson=>listeningOnly?(lesson.skill||'listening')==='listening'&&['practice','exam'].includes(lesson.type):lesson.skill===skill)}:teacher.materials;
  return `<div class="section-head"><div><h2>${listeningOnly?'Listening Lab':'Learning Materials'}</h2><p class="small muted">${listeningOnly?'Your uploaded Listening tests with their matching papers, teacher guides and answer keys.':'Your books, uploaded recordings, teacher slides and answer keys.'} No student class code is needed.</p></div>${action(teacher.materialsLoading?'Loading materials…':'Refresh materials','teacher-materials-retry',teacher.materialsLoading?'disabled':'','secondary')}</div>`+error+(catalog?materialsPage({role:'teacher',catalog,listeningOnly}):teacher.materialsError?'':materialsPage({role:'teacher',catalog:null,listeningOnly}));
}
async function refreshTeacher(){
  teacher.loading=true;teacher.error='';options.onChange?.();
  try{
    const query=new URLSearchParams({...teacher.filters,offset:String(teacher.offset)});
    const [summary,students,list]=await Promise.all([teacherRequest('/api/teacher/summary'),teacherRequest('/api/teacher/students?archived=1'),teacherRequest('/api/teacher/submissions?'+query)]);
    teacher.summary=summary;teacher.students=students.students;teacher.archived=students.archived||[];teacher.submissions=list.submissions;teacher.total=list.total;
  }catch(e){teacher.error=e.message;}finally{teacher.loading=false;options.onChange?.();}
}
function detailHTML(row){
  const p=row.payload,draft=teacher.reviewDrafts[row.id]||{feedback:row.feedback,teacherScore:row.teacher_score,reviewed:!!row.reviewed};
  let work=p.kind==='writing'?`<section class="card"><div class="eyebrow">${p.result.wordCount} WORDS · ${p.context==='homework'?'WEEK '+p.week+' HOMEWORK':p.context==='weekly-mock'?'WEEK '+p.week+' MOCK':p.context==='mock'?'MOCK TEST':'WRITING PRACTICE'}</div><h3>${esc(p.title)}</h3><p class="small muted">${esc(p.prompt)}</p>${p.table?`<div class="table-wrap"><table><caption>${esc(p.table.title)} · ${esc(p.table.units)}</caption><thead><tr>${p.table.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${p.table.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}<h4>Original student response</h4><div class="corrected-text">${esc(p.text||'(No response)')}</div><details><summary>Common-error grammar feedback</summary><p class="small muted">Rule-based checks; no automatic IELTS band.</p><div class="corrected-text">${esc(p.result.corrected)}</div>${p.result.issues.map(i=>`<p class="small"><del>${esc(i.original)}</del> → ${esc(i.replacement)}<br>${esc(i.message)}</p>`).join('')}</details></section>`:p.details?`<section class="card"><h3>${p.total?p.score+'/'+p.total+' practice marks':'Saved answers for teacher review'}</h3><p class="small muted">${p.source==='student-book'?'Student-book activity · '+p.answeredCount+' / '+p.questionCount+' answered. '+(p.pendingCount?p.pendingCount+' responses need teacher review.':'Verified answers are auto-marked.'):'Marks recalculated from the submitted answers. These original activities are not calibrated to IELTS bands.'}</p>${p.details.map((q,i)=>`<div class="question"><strong>${i+1}. ${esc(q.text)}</strong><p>Your answer: ${esc(q.given||'(blank)')}</p><div class="feedback ${q.correct?'correct':''}"><strong>${q.correct===null?'Teacher review':q.correct?'✓ Correct':'Review this answer'}</strong>${q.answer?' · Expected: '+esc(Array.isArray(q.answer)?q.answer[0]:q.answer):''}<small>${esc(q.evidence)}</small></div></div>`).join('')}</section>`:`<section class="card"><h3>Speaking preparation and self-review</h3><div class="corrected-text">${esc(p.notes||'No preparation notes saved.')}</div><p class="small muted">Open the student recording in Audio attachments. Students may upload up to three attempts; only their latest recording is kept. Speaking needs your review, with no automatic band.</p></section>`;
  return `<div class="section-head"><div><span class="pill">${esc(row.student_name)}</span><h2>${esc(row.title)}</h2><p class="small muted">${date(row.created_at)} · ${row.reviewed?'Reviewed':'Awaiting review'}</p></div>${action('Back to inbox','back-inbox','','secondary')}</div><div class="teacher-review-grid">${work}<aside class="card teacher-review"><h3>Your feedback</h3>${p.kind==='writing'?`<div class="teacher-ai-review">${row.automaticFeedback?.report?`<div class="notice"><strong>AI draft ready for your review</strong><p class="small">Add it below to check and edit. Existing editor text is kept.</p>${action('Add AI draft to editor','use-automatic-draft','','soft')}<details><summary>Inspect private AI draft</summary>${automaticDraftHTML(row.automaticFeedback)}</details></div>`:''}${action(teacher.aiBusy===row.id?'Preparing AI suggestions…':'Generate AI correction suggestions','teacher-ai-review',teacher.aiBusy===row.id?'disabled':'','soft')}<p class="small muted">Suggestions stay private. Edit them below, then publish your feedback when ready.</p>${action('Copy for ChatGPT','copy-chatgpt','','secondary')}<p class="small muted">Paste the copied prompt into ChatGPT, then paste its response into the feedback editor below. Your subscription can be used for this manual step.</p><details><summary>View prompt to copy</summary><textarea id="chatGPTPrompt" rows="6" readonly>${esc(chatGPTReviewPrompt(p))}</textarea></details>${teacher.aiReports?.[row.id]?`<details><summary>Inspect marked passages & AI assessment</summary>${writingFeedbackHTML(teacher.aiReports[row.id],p.text,{teacher:true})}</details>`:''}</div>`:''}<form id="reviewForm"><label for="teacherFeedback">Feedback for this student</label><p class="small muted">Copy and paste are enabled here. Paste feedback from ChatGPT, then edit it before publishing.</p><textarea id="teacherFeedback" rows="9" maxlength="10000" spellcheck="true" placeholder="Paste or type your feedback here…">${esc(draft.feedback)}</textarea><label for="teacherMark">Teacher mark (optional)</label><input id="teacherMark" maxlength="30" value="${esc(draft.teacherScore||'')}" placeholder="e.g. Band 7.5 (Writing) or 15/20"><p class="small muted">Edit freely, then save privately or publish to this student. ${row.reviewed?'Saving privately removes the current feedback from the student view until you publish again. ':''}For a Writing graph mark, enter Band 7.5 or a band from 0–9.</p><div class="button-row"><button type="submit" value="draft" class="button secondary" ${teacher.fileBusy?'disabled':''}>${row.reviewed?'Unpublish & save draft':'Save private draft'}</button><button type="submit" value="publish" class="button" ${teacher.fileBusy?'disabled':''}>Publish feedback →</button></div></form>${teacherFeedbackFilesHTML(row)}${teacherAudioHTML(row)}<div style="margin-top:16px">${action('Download this work','download-work','','secondary')}</div></aside></div>`;
}
function inboxHTML(){return (teacher.filters.student?writingProgressHTML(teacher.submissions):'')+`<div class="class-filters"><label>Student<select id="teacherStudent"><option value="">All students</option>${teacher.students.map(s=>`<option value="${s.id}" ${teacher.filters.student===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Skill<select id="teacherKind"><option value="">All skills</option>${['writing','reading','listening','speaking'].map(k=>`<option ${teacher.filters.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Activity<select id="teacherContext"><option value="">All activities</option>${[['homework','Homework'],['weekly-mock','Weekly mocks'],['mock','Extra mock'],['practice','Skill practice']].map(([v,l])=>`<option value="${v}" ${teacher.filters.context===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Week<select id="teacherWeek"><option value="">All weeks</option>${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${teacher.filters.week===String(i+1)?'selected':''}>Week ${i+1}</option>`).join('')}</select></label><label>Status<select id="teacherReviewed"><option value="">All submissions</option><option value="0" ${teacher.filters.reviewed==='0'?'selected':''}>Awaiting review</option><option value="1" ${teacher.filters.reviewed==='1'?'selected':''}>Reviewed</option></select></label></div><section class="card">${teacher.submissions.length?`<div class="table-wrap"><table class="inbox-table"><thead><tr><th>Student & activity</th><th>Result</th><th>Status</th><th></th></tr></thead><tbody>${teacher.submissions.map(s=>`<tr><td><strong>${esc(s.student_name)}</strong><div>${esc(s.title)}</div><small>${date(s.created_at)}</small></td><td>${s.total?s.score+'/'+s.total+' marks':s.words!=null?s.words+' words':'Speaking notes'}</td><td><span class="pill ${s.reviewed?'cloud-sent':''}">${s.reviewed?'Reviewed':(s.auto_feedback_status==='awaiting_review'||s.auto_feedback_status==='completed')?'AI draft ready':'To review'}</span></td><td>${action('Open work ↗','open-work',`data-id="${s.id}"`,'soft')}</td></tr>`).join('')}</tbody></table></div><div class="class-pagination"><span>${teacher.offset+1}–${Math.min(teacher.offset+50,teacher.total)} of ${teacher.total}</span><div class="button-row">${action('Previous','previous',teacher.offset===0?'disabled':'','secondary')}${action('Next','next',teacher.offset+50>=teacher.total?'disabled':'','secondary')}</div></div>`:'<div class="empty"><h3>Your inbox is ready.</h3><p>Add your students, give each their own code, and ask them to join the class before submitting an activity.</p></div>'}</section>`;}
let aiSettings=null,aiSettingsFlight=null,automaticSettings=null;
async function loadAISettings(){if(aiSettingsFlight||aiSettings||!teacher.loggedIn)return;aiSettingsFlight=Promise.all([teacherRequest('/api/teacher/writing-settings'),teacherRequest('/api/teacher/automatic-feedback')]).then(([data,automatic])=>{if(teacher.loggedIn){aiSettings=data;automaticSettings=automatic;}}).catch(e=>{teacher.error=e.message;}).finally(()=>{aiSettingsFlight=null;options.onChange?.();});}
function aiSettingsHTML(){return `<section class="card teacher-ai-settings"><h3>Gemini writing feedback</h3><p>Encouraging comments, short corrections with explanations, and focused revision tips for your adult IELTS class. Gemini is the only AI provider used for new reviews.</p><p class="notice">${aiSettings?aiSettings.configured?'A Gemini API key is securely saved. '+(aiSettings.enabled?'Gemini coaching is enabled.':'Gemini coaching is paused until the checks below are confirmed.'):'Add your Gemini API key below. Earlier OpenAI keys are not used. Basic checks and teacher feedback remain available.':'Opening Gemini settings…'}</p><form id="teacherAISettingsForm"><label for="writingAPIKey">Gemini API key ${aiSettings?.configured?'(leave blank to keep your saved Gemini key)':''}</label><input id="writingAPIKey" type="password" autocomplete="new-password" spellcheck="false" placeholder="AIza…"><label for="writingAIModel">Writing model</label><select id="writingAIModel"><option>gemini-3.5-flash-lite</option></select><label class="check-item"><input id="writingAIEnabled" type="checkbox" ${aiSettings?.enabled!==false?'checked':''}>Enable Gemini writing reviews</label><label class="check-item"><input id="geminiEligible" type="checkbox" ${aiSettings?.eligible?'checked':''}>This app is for adults 18+, and writing sent to Gemini excludes personal, confidential, and sensitive information. I understand free-tier content may be used to improve Google products and reviewed by people.</label><label class="check-item"><input id="removeWritingKey" type="checkbox">Remove the saved Gemini API key</label><button class="button" ${!aiSettings?'disabled':''}>Save Gemini settings</button></form><p class="small muted">Use a free-tier Google AI Studio project without billing enabled to avoid API charges. Free quotas and model availability can change. The app cannot verify your Google billing tier and will not enable billing or fall back to OpenAI. Keys are encrypted in private server storage. One-hour background scheduling remains a separate service.</p><a href="https://aistudio.google.com/api-keys" target="_blank" rel="noopener noreferrer">Get a Gemini API key ↗</a> · <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Google API terms ↗</a></section>`;}
function rosterHTML(){return `<div class="teacher-roster-grid"><section class="card"><h3>Your students</h3><p class="small muted">Give each student their own code and the usual Richmount student link. Their code is their first password. Use Reset password if they forget their chosen password.</p>${teacher.students.length?teacher.students.map(s=>`<article class="roster-row"><form data-rename="${s.id}" class="roster-name"><label class="sr-only" for="name-${s.id}">Student name</label><input id="name-${s.id}" name="name" maxlength="60" required value="${esc(s.name)}"><button class="button soft">Save name</button></form><div class="class-code"><code>${esc(s.code)}</code>${action('Copy code','copy-code',`data-code="${esc(s.code)}"`,'secondary')}${action('Reset password','reset-student-password',`data-id="${s.id}"`,'secondary')}${action('Delete student','remove-student',`data-id="${s.id}"`,'secondary')}</div></article>`).join(''):'<p>No students added yet.</p>'}${teacher.archived.length?`<details class="removed-students"><summary>Removed students (${teacher.archived.length})</summary><p class="small muted">Their class codes are inactive. Past work and attendance remain recorded.</p>${teacher.archived.map(s=>`<div class="roster-row"><strong>${esc(s.name)}</strong>${action('Restore student','restore-student',`data-id="${s.id}"`,'secondary')}</div>`).join('')}</details>`:''}</section><section class="card"><h3>Add students</h3><form id="addStudentsForm"><label for="studentNames">One student name per line</label><textarea id="studentNames" rows="10" placeholder="Anu Batbold\nTemuulen Enkh" required>${esc(teacher.bulkDraft)}</textarea><p class="small muted">Add your 10 learners together. You can add up to 20 at a time.</p><button class="button">Create individual class codes →</button></form></section></div>`;}
export function teacherPage(){
  const requested=location.hash.slice(1).split('/')[1];
  if(TEACHER_VIEWS.includes(requested)&&teacher.view!==requested){teacher.view=requested;teacher.detail=null;teacher.error='';}
  const base=apiBase();
  if(base&&base!==location.origin)return `<div class="page-head"><div class="eyebrow">FOR TEACHER ANGELO</div><h1>Your private teacher dashboard.</h1><p>Review submitted work and open your teaching materials in your teacher space.</p></div><section class="card"><a class="button" href="${esc(base+'/'+teacherLocation(location.hash))}">Open teacher dashboard ↗</a><p class="small muted">Your teacher password is required. Students can continue using this studio.</p></section>`;
  if(!teacher.loggedIn)return `<div class="page-head"><div class="eyebrow">YOUR CLASS, IN ONE PLACE</div><h1>Teacher dashboard.</h1><p>Sign in to review your students’ submitted work.</p></div><section class="card teacher-login"><h2>Welcome, Teacher Angelo.</h2>${teacher.error?`<div class="notice warm" role="alert">${esc(teacher.error)}</div>`:''}<form id="teacherLoginForm"><label for="teacherPassword">Teacher password</label><input id="teacherPassword" type="password" required autocomplete="current-password"><button class="button" ${!base?'disabled':''}>Sign in →</button></form><p class="small muted">Students use their own individual class codes. This password is for you only.</p></section>`;
  if(teacher.view==='settings')void loadAISettings();
  if(teacherCourseViews.includes(teacher.view)){void loadTeacherCourse();const id=location.hash.slice(1).split('/')[2];if(id)void loadTeacherPreview(id);}
  return `<div class="page-head"><div class="eyebrow">RICHMOUNT · TEACHER ANGELO</div><h1>Your students. Their next steps.</h1><p>Original responses, practice marks and your feedback, together.</p></div><div class="stats class-stats"><div class="stat"><strong>${teacher.summary.students??'—'}</strong><small>Students</small></div><div class="stat"><strong>${teacher.summary.submissions??'—'}</strong><small>Submitted activities</small></div><div class="stat"><strong>${teacher.summary.awaitingReview??'—'}</strong><small>Awaiting your review</small></div></div><div class="section-head"><div class="tabs">${teacherTabs.map(v=>action(teacherPages[v],'teacher-view',`data-view="${v}"`,'tab '+(teacher.view===v?'active':''))).join('')}</div><div class="button-row">${action(teacher.loading?'Refreshing…':'Refresh','teacher-refresh',teacher.loading?'disabled':'','secondary')}</div></div>${teacher.error?`<div class="notice warm" role="alert">${esc(teacher.error)}</div>`:''}${teacher.detail?detailHTML(teacher.detail):teacher.view==='grades'?bookGradesHTML():teacher.view==='students'?rosterHTML():teacher.view==='course'?teacherCourseHTML():teacher.view==='homework'?teacherCourseHTML({mode:'homework'}):teacher.view==='mock'?teacherCourseHTML({mode:'mock'}):teacher.view==='reading'?teacherMaterialsHTML(false,'reading')+(options.teacherContent?.('reading')||''):['attendance','overview','deliverables','lessons','writing','speaking','guides','official','vocabulary'].includes(teacher.view)?options.teacherContent?.(teacher.view)||'':teacher.view==='resources'?teacherMaterialsHTML():teacher.view==='listening'?(options.teacherContent?.('official-shortcut')||'')+teacherMaterialsHTML(true):teacher.view==='audio'?teacherLibraryHTML():teacher.view==='settings'?automaticSettingsHTML(automaticSettings)+aiSettingsHTML()+`<section class="card teacher-login"><h3>Change your teacher password</h3><form id="teacherPasswordForm"><label for="currentPassword">Current password</label><input id="currentPassword" type="password" autocomplete="current-password" required><label for="newTeacherPassword">New password (at least 12 characters)</label><input id="newTeacherPassword" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><label for="confirmTeacherPassword">Confirm new password</label><input id="confirmTeacherPassword" type="password" autocomplete="new-password" minlength="12" required><button class="button">Save new password</button></form><p class="small muted">Changing your password signs out your other teacher sessions. Class codes and submitted work stay available.</p></section>`:inboxHTML()}`;
}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function initClassroom(callbacks){
  options=callbacks;client=createStudentSync({storage:localStorage,fetcher:fetch.bind(globalThis),apiBase:CLASSROOM_API.replace(/\/$/,''),onJoined:callbacks.onJoined,onChange:()=>{const d=client.info();if(d.student?.passwordChangeRequired&&location.hash!=='#class')location.hash='class';if(studentMaterialsOwner!==(d.student?.id||'')){clearStudentMaterials();studentMaterialsOwner=d.student?.id||'';}const badge=document.querySelector('#classroomBadge');if(badge)badge.textContent=d.student?(d.pending?'Waiting to send · '+d.pending:'✓ Teacher connected'):'Join your class';callbacks.onChange?.();}});
  initClassAudio({studentRequest:(...args)=>client.request(...args),teacherRequest,studentId,onChange:callbacks.onChange,toast:callbacks.toast,uploadDraft:callbacks.uploadSpeakingDraft,teacherDetailId:()=>teacher.detail?.id,reloadTeacherDetail:async()=>{if(teacher.detail)teacher.detail=(await teacherRequest('/api/teacher/submissions/'+teacher.detail.id)).submission;}});
  window.addEventListener('online',()=>{if(!isTeacherSite())void client.flush();});
  if(!isTeacherSite())void client.verify().catch(()=>{});
  if(apiBase()===location.origin)void teacherRequest('/api/teacher/session').then(()=>{teacher.loggedIn=true;return refreshTeacher();}).catch(()=>{});
  document.querySelector('#app').addEventListener('submit',async e=>{
    const form=e.target;if(!['classJoinForm','studentPasswordForm','teacherLoginForm','addStudentsForm','reviewForm','teacherPasswordForm','teacherAISettingsForm'].includes(form.id)&&!form.dataset.rename)return;
    e.preventDefault();const button=form.querySelector('button');if(button)button.disabled=true;
    try{
      if(form.id==='classJoinForm'){await client.join(form.querySelector('#classCode').value,form.querySelector('#studentLoginPassword').value);studentPasswordError='';location.hash='class';callbacks.toast?.(client.info().student?.passwordChangeRequired?'Signed in. Choose your new password below.':'You are connected to Teacher Angelo.');}
      else if(form.id==='studentPasswordForm'){const next=form.querySelector('#studentNewPassword').value,confirm=form.querySelector('#studentConfirmPassword').value;if(next!==confirm)throw new Error('The new passwords do not match.');await client.changePassword(form.querySelector('#studentCurrentPassword').value,next,confirm);studentPasswordError='';callbacks.onChange?.();callbacks.toast?.('Your new password is saved. Use your student code and new password next time.');}
      else if(form.id==='teacherLoginForm'){await teacherRequest('/api/teacher/login',{method:'POST',body:JSON.stringify({password:form.querySelector('#teacherPassword').value})});teacher.loggedIn=true;await refreshTeacher();}
      else if(form.id==='addStudentsForm'){await teacherRequest('/api/teacher/students',{method:'POST',body:JSON.stringify({names:form.querySelector('#studentNames').value.split('\n').map(n=>n.trim()).filter(Boolean)})});teacher.bulkDraft='';await refreshTeacher();callbacks.toast?.('Your student codes are ready.');}
      else if(form.dataset.rename){await teacherRequest('/api/teacher/students/'+form.dataset.rename,{method:'PATCH',body:JSON.stringify({name:form.querySelector('input').value})});await refreshTeacher();callbacks.toast?.('Student name saved.');}
      else if(form.id==='reviewForm'){const publish=e.submitter?.value==='publish';if(teacher.fileBusy)throw new Error('Wait for your files to finish uploading.');if(publish&&!form.querySelector('#teacherFeedback').value.trim()&&!teacher.detail.attachments?.length)throw new Error('Write feedback or attach a file before publishing.');await teacherRequest('/api/teacher/submissions/'+teacher.detail.id,{method:'PATCH',body:JSON.stringify({feedback:form.querySelector('#teacherFeedback').value,teacherScore:form.querySelector('#teacherMark').value,attachmentIds:(teacher.detail.attachments||[]).map(f=>f.id),reviewed:publish})});delete teacher.reviewDrafts[teacher.detail.id];teacher.detail=(await teacherRequest('/api/teacher/submissions/'+teacher.detail.id)).submission;await refreshTeacher();callbacks.toast?.(teacher.detail.reviewed?'Your feedback is published for the student.':'Your feedback is saved privately.');}
      else if(form.id==='teacherAISettingsForm'){const secret=form.querySelector('#writingAPIKey').value.trim();form.querySelector('#writingAPIKey').value='';aiSettings=await teacherRequest('/api/teacher/writing-settings',{method:'POST',body:JSON.stringify({apiKey:secret,geminiEligible:form.querySelector('#geminiEligible').checked,model:form.querySelector('#writingAIModel').value,enabled:form.querySelector('#writingAIEnabled').checked,removeKey:form.querySelector('#removeWritingKey').checked})});callbacks.onChange?.();callbacks.toast?.('AI settings saved securely.');}
      else if(form.id==='teacherPasswordForm'){const next=form.querySelector('#newTeacherPassword').value;if(next!==form.querySelector('#confirmTeacherPassword').value)throw new Error('The new passwords do not match.');await teacherRequest('/api/teacher/password',{method:'POST',body:JSON.stringify({currentPassword:form.querySelector('#currentPassword').value,newPassword:next})});callbacks.onChange?.();callbacks.toast?.('Your teacher password has been changed.');}
    }catch(err){if(form.id==='studentPasswordForm'){studentPasswordError=err.message;callbacks.onChange?.();}else if(form.id!=='classJoinForm'){teacher.error=err.message;callbacks.onChange?.();}callbacks.toast?.(err.message);}finally{if(button)button.disabled=false;}
  });
  function keepTeacherDraft(e){
    if(e.target.id==='studentNames')teacher.bulkDraft=e.target.value;
    if(teacher.detail&&['teacherFeedback','teacherMark'].includes(e.target.id)){
      const form=document.querySelector('#reviewForm');if(form)teacher.reviewDrafts[teacher.detail.id]={feedback:form.querySelector('#teacherFeedback').value,teacherScore:form.querySelector('#teacherMark').value,reviewed:false};
    }
  }
  document.querySelector('#app').addEventListener('input',keepTeacherDraft);
  document.querySelector('#app').addEventListener('change',async e=>{
    const input=e.target,id=input.dataset?.feedbackUpload;if(!id||teacher.fileBusy||!teacher.loggedIn||teacher.detail?.id!==id)return;
    const files=Array.from(input.files||[]);if(!files.length)return;keepFeedbackEditor();const generation=teacherSessionGeneration;teacher.fileBusy=true;callbacks.onChange?.();let saved=0;
    try{if((teacher.detail.attachments||[]).length+files.length>10)throw new Error('Each activity can have up to 10 feedback files.');
      for(const file of files){if(generation!==teacherSessionGeneration||!teacher.loggedIn)break;if(!file.size||file.size>10*1024*1024)throw new Error('Choose files of 10 MB or less.');if(!/\.(pdf|docx|txt|png|jpe?g|webp)$/i.test(file.name))throw new Error('Choose a PDF, DOCX, TXT, PNG, JPG or WebP file.');
        await teacherRequest('/api/teacher/submissions/'+id+'/feedback-files?filename='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':file.type||'application/octet-stream'},audio:true});saved++;
      }callbacks.toast?.(saved+' feedback '+(saved===1?'file':'files')+' saved privately. Publish when ready.');
    }catch(err){callbacks.toast?.((saved?saved+' files saved. ':'')+err.message);}
    finally{if(generation===teacherSessionGeneration){try{if(teacher.loggedIn&&teacher.detail?.id===id)teacher.detail=(await teacherRequest('/api/teacher/submissions/'+id)).submission;}catch(err){teacher.error=err.message;}teacher.fileBusy=false;callbacks.onChange?.();}}
  });
  document.querySelector('#app').addEventListener('change',e=>{
    keepTeacherDraft(e);
    const filters={teacherStudent:'student',teacherKind:'kind',teacherReviewed:'reviewed',teacherContext:'context',teacherWeek:'week'};if(filters[e.target.id]){teacher.filters[filters[e.target.id]]=e.target.value;teacher.filters.weekly='';teacher.offset=0;void refreshTeacher();}
  });
  document.querySelector('#app').addEventListener('click',async e=>{
    const b=e.target.closest('[data-cloud-action]');if(!b)return;const a=b.dataset.cloudAction;
    try{
      if(a==='view-feedback-files'){
        const owner=studentId(),result=await client.request('/api/student/submissions/'+b.dataset.id+'/feedback-files');if(owner!==studentId())return;const target=document.querySelector('[data-feedback-files="'+b.dataset.id+'"]');if(target)target.innerHTML=feedbackFileList(result.attachments,'student');
      }
      else if(a==='download-feedback-file'){
        const role=b.dataset.role,owner=studentId();b.disabled=true;try{const blob=await (role==='teacher'?teacherRequest:client.request)('/api/'+role+'/feedback-files/'+b.dataset.id,{binary:true,audio:true});if(role==='student'&&owner!==studentId())return;saveFeedbackDownload(blob,b.dataset.filename);}finally{b.disabled=false;}
      }
      else if(a==='remove-feedback-file'&&teacher.detail){
        if(!confirm('Remove this feedback file? The student will no longer be able to download it.'))return;keepFeedbackEditor();const id=teacher.detail.id;await teacherRequest('/api/teacher/feedback-files/'+b.dataset.id,{method:'DELETE',body:'{}'});if(teacher.detail?.id===id)teacher.detail=(await teacherRequest('/api/teacher/submissions/'+id)).submission;callbacks.onChange?.();callbacks.toast?.('Feedback file removed.');
      }
      else if(a==='retry')await client.flush();
      else if(a==='automatic-feedback'){const owner=client.info().student?.id;if(!owner)return;b.disabled=true;try{const result=await client.request('/api/student/submissions/'+b.dataset.id+'/automatic-feedback');if(client.info().student?.id!==owner)return;const target=document.querySelector('[data-automatic-report=\"'+b.dataset.id+'\"]');if(target)target.innerHTML=automaticFeedbackHTML(result.feedback);}finally{b.disabled=false;}return;}
      else if(a==='retry-automatic-feedback'){await teacherRequest('/api/teacher/automatic-feedback/retry',{method:'POST',body:'{}'});automaticSettings=(await teacherRequest('/api/teacher/automatic-feedback'));callbacks.onChange?.();callbacks.toast?.('Failed reviews are queued for another background attempt.');}
      else if(a==='student-refresh')await client.refresh();
      else if(a==='student-materials-retry'){const loading=loadStudentMaterials(true);callbacks.onChange?.();await loading;}
      else if(a==='leave')await logoutClassroom();
      else if(a==='choose-saved')location.hash='progress';
      else if(a==='send-entry'){const entry=callbacks.history().find(h=>h.id===b.dataset.entry);if(entry&&confirm('Send this completed activity as '+client.info().student.name+'? Send only your own work.')){client.queue(entry);callbacks.toast?.('Your activity is queued for your teacher.');}}
      else if(a==='reset-student-password'){const learner=teacher.students.find(s=>s.id===b.dataset.id);if(!learner||!confirm('Reset the password for '+learner.name+'? Their student code will be their temporary password, and they will choose a new one. Their saved work stays available.'))return;b.disabled=true;try{const result=await teacherRequest('/api/teacher/students/'+learner.id+'/reset-password',{method:'POST',body:'{}'});callbacks.toast?.(result.message);}finally{b.disabled=false;}}
      else if(a==='teacher-refresh'){await refreshTeacher();if(teacherCourseViews.includes(teacher.view))await loadTeacherCourse(true);if(teacher.view==='lessons')await refreshGuidedLessons();if(['resources','listening','reading'].includes(teacher.view))await loadTeacherMaterials(true);}
      else if(a==='teacher-view'){if(!TEACHER_VIEWS.includes(b.dataset.view))return;teacher.view=b.dataset.view;teacher.detail=null;teacher.error='';location.hash='teacher/'+teacher.view;callbacks.onChange?.();if(teacherCourseViews.includes(teacher.view))await loadTeacherCourse();if(['resources','listening','reading'].includes(teacher.view))await loadTeacherMaterials();}
      else if(a==='teacher-materials-retry'){const loading=loadTeacherMaterials(true);callbacks.onChange?.();await loading;}
      else if(a==='teacher-logout')await logoutClassroom();
      else if(a==='copy-chatgpt'&&teacher.detail?.payload.kind==='writing'){
        const prompt=chatGPTReviewPrompt(teacher.detail.payload);try{await navigator.clipboard.writeText(prompt);callbacks.toast?.('Copied. Paste into ChatGPT, then paste the feedback into your editor.');}catch{const field=document.querySelector('#chatGPTPrompt');field.closest('details').open=true;field.focus();field.select();callbacks.toast?.('Prompt selected. Copy it with your keyboard, then paste into ChatGPT.');}
      }
      else if(a==='use-automatic-draft'&&teacher.detail?.automaticFeedback?.report){
        const row=teacher.detail,form=document.querySelector('#reviewForm'),text=feedbackDraftText(row.automaticFeedback.report),current=form.querySelector('#teacherFeedback').value;
        if(current.includes(text)){callbacks.toast?.('This AI draft is already in your editor. You can edit it below.');return;}
        const merged=(current?current+'\n\n':'')+text;if(merged.length>10000){callbacks.toast?.('The combined feedback exceeds 10,000 characters. Shorten your editor text before adding the draft.');return;}
        teacher.reviewDrafts[row.id]={feedback:merged,teacherScore:form.querySelector('#teacherMark').value,reviewed:false};callbacks.onChange?.();callbacks.toast?.('AI draft added privately. Check and edit before publishing.');
      }
      else if(a==='teacher-ai-review'&&teacher.detail?.payload.kind==='writing'){
        const row=teacher.detail,form=document.querySelector('#reviewForm');teacher.reviewDrafts[row.id]={feedback:form.querySelector('#teacherFeedback').value,teacherScore:form.querySelector('#teacherMark').value,reviewed:false};
        teacher.aiBusy=row.id;callbacks.onChange?.();try{const result=await teacherRequest('/api/teacher/submissions/'+row.id+'/writing-review',{method:'POST',body:'{}',ai:true});if(!teacher.loggedIn)return;teacher.aiReports??={};teacher.aiReports[row.id]=result.report;
          const r=result.report,text=[r.summary,...r.strengths.map(s=>'Strength: '+s),...r.annotations.map(a=>'“'+a.quote+'”: '+a.explanation+'\nRevision hint: '+a.hint+(a.teacherSuggestion?'\nPossible correction: '+a.teacherSuggestion:'')),...r.nextSteps.map(s=>'Next step: '+s)].join('\n\n');const draft=teacher.reviewDrafts[row.id];draft.feedback=(draft.feedback?draft.feedback+'\n\n':'')+text;draft.feedback=draft.feedback.slice(0,10000);if(!draft.teacherScore&&r.bandEstimate!==null)draft.teacherScore='Band '+r.bandEstimate.toFixed(1);draft.reviewed=false;callbacks.toast?.('AI suggestions are private. Review and edit before publishing.');
        }finally{teacher.aiBusy='';callbacks.onChange?.();}
      }
      else if(a==='open-work'){teacher.detail=(await teacherRequest('/api/teacher/submissions/'+b.dataset.id)).submission;teacher.error='';callbacks.onChange?.();window.scrollTo(0,0);}
      else if(a==='back-inbox'){teacher.detail=null;callbacks.onChange?.();}
      else if(a==='next'||a==='previous'){teacher.offset=Math.max(0,teacher.offset+(a==='next'?50:-50));await refreshTeacher();}
      else if(a==='remove-student'){const student=teacher.students.find(s=>s.id===b.dataset.id);if(!student||!confirm('Delete '+student.name+' from the active roster? Their class code will stop working. Past work and attendance will remain recorded.'))return;b.disabled=true;await teacherRequest('/api/teacher/students/'+student.id,{method:'DELETE',body:'{}'});await refreshTeacher();callbacks.toast?.('Student removed. Past work and attendance are kept.');}
      else if(a==='restore-student'){b.disabled=true;await teacherRequest('/api/teacher/students/'+b.dataset.id+'/restore',{method:'POST',body:'{}'});await refreshTeacher();callbacks.toast?.('Student restored to the active roster.');}
      else if(a==='copy-code'){try{await navigator.clipboard.writeText(b.dataset.code);callbacks.toast?.('Class code copied.');}catch{callbacks.toast?.('Select and copy the class code shown beside this button.');}}
      else if(a==='download-work'){const d=teacher.detail;download('Richmount_Student_Work.txt',`RICHMOUNT IELTS · STUDENT WORK\nStudent: ${d.student_name}\nActivity: ${d.title}\nSubmitted: ${date(d.created_at)}\n\n`+(d.payload.kind==='writing'?d.payload.text:d.payload.details?d.payload.details.map((q,i)=>`${i+1}. ${q.text}\nStudent answer: ${q.given||'(blank)'}\nExpected: ${q.answer}\n${q.correct?'Correct':'Incorrect'}`).join('\n\n'):d.payload.notes)+`\n\nTEACHER FEEDBACK\n${d.feedback||'Not reviewed yet.'}\n${d.teacher_score||''}`);}
    }catch(err){teacher.error=err.message;callbacks.onChange?.();callbacks.toast?.(err.message);}
  });
}
